// === Tab: mySketch ===
let numAttractors = 0;
let numParticles = 100;

let attractors = [];
let particlePos = [];
let particleVel = [];
let gravity = 2;

function setup() {
	createCanvas(windowWidth, windowHeight);

	reset();
}

function draw() {
	fill(0, 5);
	noStroke();
	rect(0, 0, width, height);

	stroke(0, 0, 255);
	attractors[numAttractors] = createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), gravity);
	for (let i = 0; i < numParticles; i++) {
		for (let j = 0; j < numAttractors+1; j++) {
			particleVel[i].add(attract(j, particlePos[i].x, particlePos[i].y));
		}
		particlePos[i].add(particleVel[i]);
		particleVel[i].mult(1/sqrt(gravity))		
		if (i == 1) stroke(255);
		// circle(particlePos[i].x, particlePos[i].y, 10);
		line(particlePos[i].x, particlePos[i].y, particlePos[i].x - particleVel[i].x, particlePos[i].y - particleVel[i].y);
	}


}
function attract(attractIndex, posX, posY) {
	let attractionForce = createVector(posX - attractors[attractIndex].x, posY - attractors[attractIndex].y);
	attractionForce.normalize();

	let amp = 1 / sqrt(dist(posX, posY, attractors[attractIndex].x, attractors[attractIndex].y));

	amp *= attractors[attractIndex].z;

	attractionForce.mult(-amp);

	return attractionForce;
}

function reset() {
	background(0);

	for (let i = 0; i < numAttractors; i++) {
		attractors[i] = createVector(random(width), random(height), random(-1, 2));
	}
	attractors[numAttractors] = createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), gravity);

	for (let i = 0; i < numParticles; i++) {
		particlePos[i] = createVector(random(width), random(height));
		particleVel[i] = createVector(0, 0);
	}
}

function keyPressed() {
	if (keyCode == LEFT_ARROW) numParticles -= ceil(sqrt(numParticles));
	if (keyCode == RIGHT_ARROW) numParticles += ceil(sqrt(numParticles));

	if (keyCode == DOWN_ARROW) numAttractors -= ceil(sqrt(numAttractors) / 5);
	if (keyCode == UP_ARROW) numAttractors += ceil(sqrt(numAttractors) / 5)+1;

	if (key == 'w') gravity++;
	if (key == 's') gravity--;

	numParticles = constrain(numParticles, 1, 1000);
	numAttractors = constrain(numAttractors, 0, 100);

	if (key != 'w' && key != 's') reset();
}

